"use client";

import { useState } from "react";
import { Select } from "ui-lab-components/select";
import { Label } from "ui-lab-components/label";

export function ModeField() {
  const [mode, setMode] = useState<string | null>(null);
  return (
    <div>
      <Label htmlFor="mode">Mode</Label>
      <Select selectedKey={mode} onSelectionChange={(key) => setMode(String(key))} className="w-full self-stretch">
        <Select.Trigger id="mode" aria-describedby="mode-help">
          <Select.Value placeholder="Choose a mode" />
        </Select.Trigger>
        <Select.Content position="bottom">
          <Select.List>
            <Select.Item value="draft">Draft</Select.Item>
            <Select.Item value="publish">Publish</Select.Item>
          </Select.List>
        </Select.Content>
      </Select>
      <p id="mode-help">Choose how this item will be saved.</p>
    </div>
  );
}
